-- 1. КНИГА (module = book)
INSERT INTO t_p29363705_audio_book_creator.creative_projects (user_id, module, title, is_example, preview, data) VALUES (
'EXAMPLE', 'book', 'Маяк на краю времени', true,
'Смотритель маяка обнаруживает, что его свет ведёт корабли не через море, а сквозь годы. Спасая чужие судьбы, он теряет собственное время.',
'{
  "bookTitle": "Маяк на краю времени",
  "genre": "Фантастика",
  "premise": "Старый смотритель маяка Эльмар замечает, что в туманные ночи его свет выводит из бури корабли, которых нет ни на одной карте — суда из прошлого и будущего. Каждый спасённый им экипаж отнимает у Эльмара часть его собственных лет. Когда из тумана появляется корабль с его погибшей женой на борту, смотритель должен выбрать: вернуть любовь или сохранить остаток жизни, чтобы спасать других.",
  "selectedTemplate": "hero",
  "characters": [
    {"id": "c1", "name": "Эльмар Свет", "role": "Протагонист", "trait": "Одинокий, преданный долгу, тоскующий по прошлому"},
    {"id": "c2", "name": "Лиа", "role": "Погибшая жена", "trait": "Тёплая, ироничная, является из тумана"},
    {"id": "c3", "name": "Капитан Норд", "role": "Антагонист", "trait": "Призрачный мореход, желающий забрать маяк себе"},
    {"id": "c4", "name": "Юна", "role": "Помощница", "trait": "Любопытная девочка из ближайшей деревни"}
  ],
  "chapters": [
    {"id": "ch1", "title": "Туман, которого не было", "summary": "Эльмар замечает первый корабль-призрак и спасает экипаж, не понимая цены.", "wordCount": 1240},
    {"id": "ch2", "title": "Часы идут назад", "summary": "Смотритель обнаруживает седину и морщины после каждой спасённой ночи.", "wordCount": 980},
    {"id": "ch3", "title": "Голос из бури", "summary": "В шуме шторма Эльмар слышит голос Лии и понимает, что туман помнит мёртвых.", "wordCount": 1120},
    {"id": "ch4", "title": "Корабль Норда", "summary": "Появляется капитан Норд и предлагает сделку: вечная жизнь в обмен на свет маяка.", "wordCount": 1310},
    {"id": "ch5", "title": "Выбор смотрителя", "summary": "Лиа возвращается. Эльмар должен решить, кого спасти — её или всех будущих моряков.", "wordCount": 1450}
  ],
  "chapterText": {
    "ch1": "Туман в ту ночь был не белым, а серебряным — как изнанка старого зеркала. Эльмар зажёг лампу ровно в семь, как делал сорок лет подряд, и луч ушёл в темноту, нащупывая горизонт.\n\nКорабль появился там, где не было фарватера. Трёхмачтовый, с парусами цвета пергамента, он шёл прямо на скалы — и всё же не разбивался. Эльмар крутил линзу, выводя судно в безопасную бухту, и не сразу заметил, что на палубе стоят люди в одеждах, каких не носили уже сто лет.\n\nУтром в бухте не было ни корабля, ни щепки. Только зеркало над камином показывало смотрителя на год старше."
  }
}'::jsonb);

-- 2. МУЛЬТФИЛЬМ (module = animation)
INSERT INTO t_p29363705_audio_book_creator.creative_projects (user_id, module, title, is_example, preview, data) VALUES (
'EXAMPLE', 'animation', 'Последний фонарщик Луны', true,
'В мире, где Луну каждую ночь зажигает фонарщик, последний из них учит маленькую девочку своему ремеслу, прежде чем свет погаснет навсегда.',
'{
  "projectTitle": "Последний фонарщик Луны",
  "format": "cartoon",
  "logline": "В мире, где Луну каждую ночь зажигает фонарщик, последний из них учит маленькую девочку своему ремеслу, прежде чем свет погаснет навсегда.",
  "scenes": [
    {"id": "s1", "number": 1, "location": "Крыша мира, лунная лестница", "time": "Ночь", "action": "Старик Фонарщик медленно поднимается по бесконечной лестнице из лунного света, неся тяжёлый фонарь. Каждая ступень загорается под его ногой и гаснет позади.", "dialogue": "ФОНАРЩИК (про себя): Ещё одна ночь. Может быть, последняя.", "mood": "Спокойствие", "duration": "0:45"},
    {"id": "s2", "number": 2, "location": "Чердак девочки", "time": "Ночь", "action": "Маленькая Мия смотрит в телескоп и видит, как Луна мигает и тускнеет. Она хватает шарф и выбегает в окно по лунному лучу.", "dialogue": "МИЯ: Луна гаснет! Так нельзя — без неё море заблудится!", "mood": "Напряжение", "duration": "0:30"},
    {"id": "s3", "number": 3, "location": "Лунная лестница", "time": "Ночь", "action": "Мия догоняет Фонарщика. Он устал и не может нести фонарь дальше. Девочка предлагает помощь.", "dialogue": "ФОНАРЩИК: Этот огонь старше меня, девочка. Он жжёт руки тех, кто не готов.\nМИЯ: А вдруг я готова?", "mood": "Грусть", "duration": "1:00"},
    {"id": "s4", "number": 4, "location": "Сердце Луны", "time": "Ночь", "action": "Вместе они доходят до погасшего сердца Луны. Фонарщик передаёт огонь Мие. Её ладони вспыхивают тёплым светом, и Луна оживает.", "dialogue": "ФОНАРЩИК: Свет не гаснет. Он просто ищет новые руки.", "mood": "Радость", "duration": "0:50"},
    {"id": "s5", "number": 5, "location": "Крыша мира", "time": "Рассвет", "action": "Фонарщик растворяется в лунном свете, улыбаясь. Мия поднимает фонарь и делает первый шаг по лестнице — новая фонарщица.", "dialogue": "МИЯ: Спокойной ночи, мир. Я присмотрю за светом.", "mood": "Спокойствие", "duration": "0:40"}
  ]
}'::jsonb);

-- 3. ПОДКАСТ (module = podcast)
INSERT INTO t_p29363705_audio_book_creator.creative_projects (user_id, module, title, is_example, preview, data) VALUES (
'EXAMPLE', 'podcast', 'Как перестать бояться и начать своё дело', true,
'Разговор с предпринимателем о том, как сделать первый шаг в бизнесе, побороть страх неудачи и найти первых клиентов без бюджета.',
'{
  "podcastName": "Дело за малым",
  "episodeTitle": "Как перестать бояться и начать своё дело",
  "format": "interview",
  "mainIdea": "Разговор с предпринимателем о том, как сделать первый шаг в бизнесе, побороть страх неудачи и найти первых клиентов без бюджета.",
  "guestName": "Анна Ковалёва, основатель сети пекарен «Тёплый угол»",
  "segments": [
    {"id": "sg1", "type": "intro", "title": "Приветствие и тема выпуска", "duration": "2:00", "notes": "Поздороваться, представить гостя, обозначить боль слушателя: «хочу своё дело, но страшно». Зацепка: история про то, как Анна пекла первые булочки на съёмной кухне."},
    {"id": "sg2", "type": "topic", "title": "Главный страх новичка", "duration": "6:00", "notes": "Обсудить страх неудачи и потери денег. Тезис: начинать нужно с минимальной проверки идеи, а не с кредита."},
    {"id": "sg3", "type": "interview", "title": "История Анны: от кухни до сети", "duration": "12:00", "notes": "Путь гостя: первый заказ, первая ошибка, момент, когда захотелось всё бросить, и что помогло остаться."},
    {"id": "sg4", "type": "tips", "title": "5 шагов первого месяца", "duration": "8:00", "notes": "Практические советы: найти 10 клиентов вручную, считать юнит-экономику, не нанимать рано, собирать отзывы, не бояться поднять цену."},
    {"id": "sg5", "type": "story", "title": "Провал, который всё изменил", "duration": "5:00", "notes": "Личная история гостя о крупной ошибке и уроке из неё."},
    {"id": "sg6", "type": "outro", "title": "Итоги и призыв к действию", "duration": "2:00", "notes": "Резюме трёх главных мыслей. Домашнее задание слушателю: поговорить с 3 потенциальными клиентами на этой неделе."}
  ],
  "questions": [
    {"id": "q1", "text": "Что вы чувствовали в день, когда решились уйти с работы ради своего дела?", "followUp": "Был ли момент, когда хотелось всё вернуть назад?"},
    {"id": "q2", "text": "Как вы нашли самых первых клиентов, когда о вас никто не знал?", "followUp": "Сколько денег ушло на привлечение первого десятка?"},
    {"id": "q3", "text": "Какую самую дорогую ошибку вы совершили в первый год?", "followUp": "Что бы вы сделали иначе сегодня?"},
    {"id": "q4", "text": "Что бы вы сказали человеку, который боится начать?", "followUp": "С чего конкретно посоветуете начать на этой неделе?"}
  ]
}'::jsonb);

-- 4. СТИХИ И ПЕСНИ (module = poem)
INSERT INTO t_p29363705_audio_book_creator.creative_projects (user_id, module, title, is_example, preview, data) VALUES (
'EXAMPLE', 'poem', 'Город под дождём', true,
'Город под дождём — Куплет 1: Асфальт глотает капли фонарей,',
'{
  "form": "song",
  "mood": "Лирика",
  "meter": "Хорей",
  "rhyme": "ABAB",
  "poemTitle": "Город под дождём",
  "verses": [
    {"id": "v1", "label": "Куплет 1", "text": "Асфальт глотает капли фонарей,\nИ зонт твой — парус в море площадей.\nМы два прохожих в книге площадей,\nДва имени на стёкол янтаре."},
    {"id": "v2", "label": "Припев", "text": "А город под дождём поёт,\nИ светофор нам мигом подмигнёт.\nЛови меня за тёплый рукав —\nДождь всё запомнит, нас не потеряв."},
    {"id": "v3", "label": "Куплет 2", "text": "Витрины тают акварельным сном,\nТрамвай уносит музыку с собой.\nМы пишем вечер мокрым серебром,\nИ каждый шаг становится строкой."},
    {"id": "v4", "label": "Припев", "text": "А город под дождём поёт,\nИ светофор нам мигом подмигнёт.\nЛови меня за тёплый рукав —\nДождь всё запомнит, нас не потеряв."},
    {"id": "v5", "label": "Бридж", "text": "Пусть гаснут окна — мы зажжём\nСвой свет в ладонях под дождём."}
  ]
}'::jsonb);

-- 5. АВАТАР-ПРОДАВЕЦ (module = avatar)
INSERT INTO t_p29363705_audio_book_creator.creative_projects (user_id, module, title, is_example, preview, data) VALUES (
'EXAMPLE', 'avatar', 'Марина — менеджер по недвижимости', true,
'Виртуальный менеджер по продаже новостроек. Тёплый эксперт, помогает подобрать квартиру и оформить ипотеку.',
'{
  "gender": "Женский",
  "appearance": "Женщина 32 лет, уверенная тёплая улыбка, деловой пиджак, аккуратное тёмное каре, доброжелательный взгляд",
  "industry": "Недвижимость",
  "product": "Новостройки ЖК «Солнечный квартал», квартиры от студий до 3-комнатных, ипотека от 5%",
  "tone": "caring",
  "voiceId": "jane",
  "avatarUrl": "https://cdn.poehali.dev/projects/84e163f9-9661-409a-9ae9-a67ebf795811/files/c7e3f855-b501-4803-bdb0-9ec8cdde5da6.jpg",
  "avatarVariants": ["https://cdn.poehali.dev/projects/84e163f9-9661-409a-9ae9-a67ebf795811/files/c7e3f855-b501-4803-bdb0-9ec8cdde5da6.jpg"],
  "knowledge": "ЖК «Солнечный квартал». Расположение: 12 минут до центра, рядом метро, школа и парк. Квартиры: студии 28 м² от 4.9 млн ₽, 1-комн. 38 м² от 6.2 млн ₽, 2-комн. 56 м² от 8.4 млн ₽, 3-комн. 78 м² от 11.9 млн ₽. Отделка: white box или под ключ (+8%). Ипотека: семейная от 5%, господдержка от 6%, стандартная от 12%. Первый взнос от 15%. Сдача дома: 4 квартал 2026. Паркинг: подземный, машино-место 1.2 млн ₽. Рассрочка от застройщика 0% до сдачи. Акция месяца: при покупке 2- и 3-комнатных — кухня в подарок.",
  "persona": {
    "name": "Марина",
    "role": "Старший менеджер по продажам недвижимости",
    "personality": "Тёплая, внимательная, никогда не давит. Сначала выясняет потребности семьи, потом предлагает варианты. Объясняет ипотеку простыми словами.",
    "greeting": "Здравствуйте! Меня зовут Марина, я помогу подобрать квартиру в ЖК «Солнечный квартал». Расскажите, для кого ищете жильё — и я предложу лучшие варианты под ваш бюджет.",
    "strengths": ["Знает все планировки наизусть", "Подбирает ипотечную программу под клиента", "Честно говорит о плюсах и минусах", "Помогает с документами от брони до сделки"]
  },
  "pitch": "ЖК «Солнечный квартал» — это дом, в который хочется возвращаться. Всего 12 минут до центра, но при этом свой парк, школа и детский сад прямо во дворе. Квартиры с продуманными планировками: от уютных студий для старта до просторных трёхкомнатных для большой семьи. Сейчас действует семейная ипотека от 5% и рассрочка 0% до сдачи дома — можно въехать, не переплачивая банку годами. А при покупке двух- или трёхкомнатной квартиры мы дарим кухню. Давайте подберём вариант именно под вашу жизнь.",
  "faq": [
    {"question": "Какой первый взнос по ипотеке?", "answer": "От 15% стоимости квартиры. По семейной ипотеке ставка от 5% — это одна из самых выгодных программ на рынке. Я помогу рассчитать ежемесячный платёж под ваш бюджет."},
    {"question": "Когда сдаётся дом?", "answer": "Сдача в 4 квартале 2026 года. До этого момента действует рассрочка от застройщика под 0% — вы платите частями без переплаты банку."},
    {"question": "Это далеко от центра?", "answer": "Всего 12 минут на машине и рядом метро. При этом у вас под окнами свой парк, школа и детский сад — не нужно никуда возить детей."},
    {"question": "Дорого ли это для семьи?", "answer": "Понимаю ваше беспокойство. Давайте посчитаем вместе: со семейной ипотекой от 5% платёж за студию сопоставим с арендой. А при покупке 2-комнатной мы ещё и дарим кухню — это серьёзная экономия."}
  ]
}'::jsonb);
